{

"kind": "propose",
"summary": "Adjust probe timeouts to accommodate application startup time",
"hypotheses": [
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Readiness and liveness probes timeout before the application can respond",
        "supporting": ["probe_timeouts", "ev-rollout_history", "ev-target_events"],
        "contradicting": [],
        "missing": ["application_startup_time_ms"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Need to verify if probe timeouts are the root cause",
        "supporting": [],
        "contradicting": ["probe_kills", "probe_timeouts"],
        "missing": ["application_startup_time_ms", "container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "search-api",
        "uid": "uid-deployment-search-api"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Reduce probe timeouts to allow the application sufficient time to respond before timing out",
    "rationale": "The application is timing out on both liveness and readiness probes (ev-target_events), but the logs show no application errors or crashes (crashed_on_its_own=false). The probes' timeoutSeconds (1s) are likely too short for the application's startup or response time. Increasing timeouts to 5s provides a buffer while maintaining probe responsiveness. This change aligns with the probe_timeout_too_short hypothesis, as the application appears functional but takes longer than the probe's allowed time to respond (ev-target_events).",
    "cited_evidence_ids": ["probe_timeouts", "ev-rollout_history", "ev-target_events", "crashed_on_its_own"],
    "cited_predicates": ["probe_timeouts", "crashed_on_its_own"]
}
}
